// Local, project-only rule — not worth publishing as a separate package.
// Enforces the "@mantine/* imports are always multi-line, one specifier per
// line" policy documented in CLAUDE.md. Prettier has no concept of
// per-package import formatting, so `prettier --write` will happily collapse
// these onto one line — this rule's autofix restores the canonical form.
// See require-multiline-mantine-import.test.mjs for coverage.
function buildMultilineImport(node, sourceCode) {
    const keyword = node.importKind === 'type' ? 'import type' : 'import';
    const specifierLines = node.specifiers.map(
        (specifier) => `    ${sourceCode.getText(specifier)},`,
    );
    const source = sourceCode.getText(node.source);

    return [`${keyword} {`, ...specifierLines, `} from ${source};`].join(
        '\n',
    );
}

export const requireMultilineMantineImport = {
    meta: {
        type: 'layout',
        fixable: 'whitespace',
        schema: [],
        messages: {
            mustBeMultiline:
                "Imports from '{{source}}' must be written multi-line, one specifier per line with a trailing comma (see CLAUDE.md).",
        },
    },
    create(context) {
        return {
            ImportDeclaration(node) {
                if (
                    typeof node.source.value !== 'string' ||
                    !node.source.value.startsWith('@mantine/')
                ) {
                    return;
                }

                // The canonical multi-line form only covers plain named
                // imports, which is the only style this codebase's Mantine
                // usage exercises — skip default/namespace specifiers rather
                // than guess at a form for them.
                if (
                    node.specifiers.length === 0 ||
                    node.specifiers.some((s) => s.type !== 'ImportSpecifier')
                ) {
                    return;
                }

                const sourceCode = context.sourceCode ?? context.getSourceCode();
                const expected = buildMultilineImport(node, sourceCode);
                const actual = sourceCode.getText(node);

                if (actual === expected) {
                    return;
                }

                context.report({
                    node,
                    messageId: 'mustBeMultiline',
                    data: { source: node.source.value },
                    fix(fixer) {
                        return fixer.replaceText(node, expected);
                    },
                });
            },
        };
    },
};

import { RuleTester } from 'eslint';

import { requireMultilineMantineImport } from './require-multiline-mantine-import.mjs';

const ruleTester = new RuleTester({
    languageOptions: {
        ecmaVersion: 'latest',
        sourceType: 'module',
        parserOptions: { ecmaFeatures: { jsx: true } },
    },
});

ruleTester.run(
    'require-multiline-mantine-import',
    requireMultilineMantineImport,
    {
        valid: [
            "import {\n    Table,\n} from '@mantine/core';",
            "import {\n    Box,\n    Collapse,\n} from '@mantine/core';",
            // Non-Mantine imports are untouched, however formatted.
            "import { fromPounds, toPounds } from '@/lib/money';",
            // Default/namespace specifiers are out of scope for this rule.
            "import Foo from '@mantine/core';",
            "import * as Foo from '@mantine/core';",
        ],
        invalid: [
            {
                code: "import { Table } from '@mantine/core';",
                output: "import {\n    Table,\n} from '@mantine/core';",
                errors: [{ messageId: 'mustBeMultiline' }],
            },
            {
                // Single-specifier imports must still be multi-line per
                // CLAUDE.md, even though they'd fit on one line.
                code: "import { Box, Collapse, Flex } from '@mantine/core';",
                output: "import {\n    Box,\n    Collapse,\n    Flex,\n} from '@mantine/core';",
                errors: [{ messageId: 'mustBeMultiline' }],
            },
            {
                // Missing trailing comma on an otherwise multi-line import.
                code: "import {\n    Box,\n    Collapse\n} from '@mantine/core';",
                output: "import {\n    Box,\n    Collapse,\n} from '@mantine/core';",
                errors: [{ messageId: 'mustBeMultiline' }],
            },
            {
                code: "import { type ButtonProps } from '@mantine/core';",
                output: "import {\n    type ButtonProps,\n} from '@mantine/core';",
                errors: [{ messageId: 'mustBeMultiline' }],
            },
        ],
    },
);

console.log('require-multiline-mantine-import: all rule tests passed');

